def _n(s): return re.sub(r'\s+', ' ', s).strip()
def _H(bl, text, start=0):
    for i in range(start, len(bl)):
        if bl[i][0] == 'h' and _n(bl[i][2]) == text: return i
    raise KeyError(text)
def _Q(bl, a, b): return [i for i in range(a, b) if bl[i][0] == 'p' and re.match(r'Q\.\d', bl[i][2])]
def _T(bl, kind, start, a=0, b=None):
    """first block of this kind whose text starts with `start`"""
    for i in range(a, len(bl) if b is None else b):
        if bl[i][0] == kind and _n(bl[i][2]).startswith(start): return i
    raise KeyError(start)
def _marks(bl):
    M = {}
    for k, t in (('atm', '1 · ATMOSPHERE'), ('heat', 'Heat & Temperature'), ('p2', '2 · PYQ'), ('inv', '3 · Temperature Inversion:'), ('pres', '4 · AIR PRESSURE & PRESSURE BELTS'), ('p5', '5 · PYQ'), ('geo', '6 · GEOSTROPHIC WINDS:'), ('loc', '8 · LOCAL WINDS'), ('mon', '9 · MONSOONAL WINDS:'), ('hum', '10 · HUMIDITY & CONDENSATION'), ('p11', '11 · PYQ'), ('air', '12 · AIR MASSES'), ('cyc', '13 · CYCLONES'), ('p14', '14 · PYQ'), ('kop', '15 · Koppen’s Classiﬁcation'), ('reg', '16 · CLIMATIC REGIONS OF THE WORLD'), ('p17', '17 · PYQs'), ('rec', 'Recall sheet')):
        M[k] = _H(bl, t, M.get('atm', 0))
    return M
def drop(bl):
    M = _marks(bl); d = set()
    for a, b in ((M['p2'], M['inv']), (M['p5'], M['geo']), (M['p11'], M['air']), (M['p14'], M['kop']), (M['p17'], M['rec'])):
        for i in range(a, b):
            if bl[i][0] in ('p', 'h'): d.add(i)
    # the 2022 Mains question and one bare answer line are printed as bullets; they live in the PYQ block instead
    d.add(_T(bl, 'li', 'The troposphere is a very signiﬁcant atmospheric layer', M['p2'], M['inv']))
    d.add(_T(bl, 'li', 'Both Statement-I and Statement-II are correct and Statement-II explains Statement-I', M['p2'], M['inv']))
    return d
